 static void xp(){
  int[] ids={1152,1154,1156,1158,1160,1163,1166,1169,1172,1175,1177,1181,1183,1185,1188,1189,23619,23633,23603,23583,1153,1157,1161,1542,1543,1562,1572,1582,1171,1539,12037,1190,1191,1192,12939,12987,12901,12861,12963,13011,12919,12881,12951,12999,12911,12871,12975,13023,12929,12891};
  double[] exp={5.5,7.5,9.5,11.5,13.5,16.5,19.5,22.5,25.5,28.5,31.5,34.5,36,37.5,40,42.5,44.5,46.5,48.2,50.5,13,21,29,76,83,90,30,60,24.5,30,30,35,35,35,30,31,33,34,36,37,39,40,42,43,45,46,48,49,51,52};
  Player p=actor();ok(ids.length==exp.length,"Reference matrix");for(int i=0;i<ids.length;i++){spell(p,ids[i]);for(boolean hit:new boolean[]{false,true})for(boolean pvp:new boolean[]{false,true})ok(CombatCastExperience.base(p,hit,pvp)==exp[i],"Historical base XP "+ids[i]);}
  spell(p,1592);ok(CombatCastExperience.base(p,true,true)==89&&CombatCastExperience.base(p,false,true)==70&&CombatCastExperience.base(p,false,false)==89,"Entangle success/PvP splash XP");spell(p,12445);ok(CombatCastExperience.base(p,true,true)==95&&CombatCastExperience.base(p,false,true)==83.6,"Tele Block success/splash XP");p.setSpellId(52);ok(CombatCastExperience.base(p,true,false)==0,"Powered staff no regular cast XP");p.usingSpecial=true;spell(p,1158);ok(CombatCastExperience.base(p,true,false)==0,"Special does not reuse last cast XP");
  System.out.println("MAGIC_CAST_XP_50_HISTORICAL_SPELLS_200_HIT_SPLASH_PVM_PVP_VALUES_ENTANGLE_TELEBLOCK_AND_POWERED_SPECIAL_EXCLUSIONS_OK");
  p=CombatMagicPaymentCheck.caster(1158,20714);p.getTomeOfFire().setTotalCharges(2);p.playerBonus[Bonus.ATTACK_MAGIC.ordinal()]=-64;CombatMagicPaymentCheck.give(p,556,4);CombatMagicPaymentCheck.give(p,558,2);NPC n=CombatMagicPaymentCheck.target(p);int magic=p.playerXP[6],hp=p.playerXP[3];
  p.attacking.attackEntity(n);ok(p.playerXP[6]==magic+11&&p.playerXP[3]==hp&&p.getTomeOfFire().getTotalCharges()==1,"First guaranteed splash has 11.5 base XP, no hitpoint XP, one charge: magic="+(p.playerXP[6]-magic)+" tenth="+p.playerXpTenths[6]+" hp="+(p.playerXP[3]-hp)+" book="+p.getTomeOfFire().getTotalCharges()+" bonus="+p.playerBonus[Bonus.ATTACK_MAGIC.ordinal()]);spell(p,1158);p.usingClickCast=true;p.attackTimer=0;p.playerBonus[Bonus.ATTACK_MAGIC.ordinal()]=-64;p.attacking.attackEntity(n);ok(p.playerXP[6]==magic+23&&p.playerXP[3]==hp&&p.getTomeOfFire().getTotalCharges()==0,"Two splashes preserve 0.5 XP and consume two charges exactly");
  System.out.println("MAGIC_CAST_ACTUAL_ATTACK_ENTITY_TWO_GUARANTEED_SPLASHES_23_FRACTIONAL_MAGIC_XP_ZERO_HP_XP_EXACT_FOUR_AIR_TWO_MIND_TWO_TOME_CHARGES_OK");
 }
 static void freezes(){int[] ids={1572,1582,1592,12861,12881,12871,12891},base={8,16,24,8,16,24,32};int[][] pieces={{0,25398},{4,25389},{7,25401},{9,25392},{10,25395}};int total=0;
  for(int mask=0;mask<32;mask++)for(int i=0;i<ids.length;i++){Player p=actor();for(int bit=0;bit<5;bit++)if((mask&(1<<bit))!=0)p.playerEquipment[pieces[bit][0]]=pieces[bit][1];spell(p,ids[i]);int ticks=base[i]+(i<3?Integer.bitCount(mask):0);ok(CombatSpellData.getFreezeTime(p)==ticks,"Swampbark exact pieces/ice exclusion "+mask+"/"+ids[i]);p.playerEquipment[5]=25574;p.getTomeOfWater().setTotalCharges(2);ok(CombatSpellData.getFreezeTime(p)==ticks,"Water tome does not extend duration");total++;}
  ok(total==224,"All armour sets");System.out.println("MAGIC_FREEZE_224_BIND_SNARE_ENTANGLE_ICE_CASES_32_SWAMPBARK_COMBINATIONS_8_16_24_32_TICKS_PLUS_ONE_PER_CORRECT_SLOT_NO_ICE_OR_TOME_EXTENSION_OK");}
 static void curses(){int[] ids={1153,1157,1161,1542,1543,1562},skills={0,2,1,1,2,0};for(int i=0;i<ids.length;i++)for(boolean water:new boolean[]{false,true}){Player p=actor(),q=actor(),other=actor();spell(p,ids[i]);if(water){p.playerEquipment[5]=25574;p.getTomeOfWater().setTotalCharges(1);}int expected=i<3?(water?92:95):(water?85:90); // Level 99: floor 4/7/9/14 drained.
   ok(CurseMagic.canCast(p,q),"Fresh player stat");CurseMagic.apply(p,q);ok(q.playerLevel[skills[i]]==expected,"Player curse "+ids[i]+"/"+water+" got "+q.playerLevel[skills[i]]);ok(!CurseMagic.canCast(p,q)&&CurseMagic.canCast(p,other),"Per-target nonstack, no global immunity");CurseMagic.apply(p,q);ok(q.playerLevel[skills[i]]==expected,"Successful repeats never stack");q.playerLevel[skills[i]]=99;ok(CurseMagic.canCast(p,q),"Restoration permits new curse");
   NPC n=CombatMagicPaymentCheck.target(p);NpcCombatDefinition original=NpcCombatDefinition.definitions.get(n.getNpcId());NpcCombatDefinition base=new NpcCombatDefinition(n);NpcCombatSkill key=skills[i]==0?NpcCombatSkill.ATTACK:skills[i]==1?NpcCombatSkill.DEFENCE:NpcCombatSkill.STRENGTH;base.setLevel(key,99);NpcCombatDefinition.definitions.put(n.getNpcId(),base);n.getCombatDefinition().setLevel(key,99);try{ok(CurseMagic.canCast(p,n),"Fresh NPC");CurseMagic.apply(p,n);ok(n.getCombatDefinition().getLevel(key)==expected&&!CurseMagic.canCast(p,n),"NPC curse and nonstack "+ids[i]);}finally{if(original==null)NpcCombatDefinition.definitions.remove(n.getNpcId());else NpcCombatDefinition.definitions.put(n.getNpcId(),original);}
  }
  System.out.println("MAGIC_SIX_CURSES_PLAYER_NPC_EFFECTS_WATER_50_PERCENT_DRAIN_BONUS_NO_STACK_OR_GLOBAL_IMMUNITY_STAT_RESTORE_RECAST_OK");
 }
 static void damage(){Player p=actor(),q=actor();spell(p,1189);p.playerEquipment[5]=20714;p.getTomeOfFire().setTotalCharges(20);MagicCombatFormula f=new MagicCombatFormula();p.playerBonus[Bonus.MAGIC_DMG.ordinal()]=15;ok(f.getMaxHit(p,q,1,1)==34,"20 fire wave x1.15 floor23 x1.5 floor34, not additive33");p.playerBonus[Bonus.MAGIC_DMG.ordinal()]=10;ok(f.getMaxHit(p,q,1,1)==33,"20x1.1x1.5");p.playerBonus[Bonus.MAGIC_DMG.ordinal()]=7;ok(f.getMaxHit(p,q,1,1)==31,"Equipment floor first21 then tome31, not32");p.playerEquipment[5]=25574;p.getTomeOfWater().setTotalCharges(20);spell(p,1185);p.playerBonus[Bonus.MAGIC_DMG.ordinal()]=15;ok(f.getMaxHit(p,q,1,1)==24,"18waterwave x1.15 floor20 then1.2=24");p.playerBonus[Bonus.MAGIC_DMG.ordinal()]=0;p.playerEquipment[9]=777;spell(p,1163);ok(f.getMaxHit(p,q,1,1)==15,"Water bolt chaos gauntlets13 x1.2 floor15");
  System.out.println("MAGIC_TOME_MULTIPLICATIVE_EQUIPMENT_THEN_TOME_SEPARATE_FLOORS_15_10_7_PERCENT_BONUSES_CHAOS_GAUNTLETS_OK");}
 static void targetEquipment()throws Exception{
  Player p=actor();NPC n=new NPC(1,1,io.xeros.model.definitions.NpcDef.forId(1)){public boolean isUndead(){return true;}};n.absX=3001;n.absY=3200;
  p.getSlayer().setTask(Optional.of(new io.xeros.content.skills.slayer.Task(new String[]{n.getName().toLowerCase()},1,10,1,1,new String[0],new int[]{3000,3200,0})));
  p.getSlayer().setTaskAmount(1);p.playerEquipment[0]=11865;p.playerEquipment[5]=20714;p.getTomeOfFire().setTotalCharges(5);p.playerBonus[Bonus.MAGIC_DMG.ordinal()]=15;spell(p,1189);MagicCombatFormula f=new MagicCombatFormula();
  ok(MagicTargetEquipment.bonus(p,n)==0.15&&f.getMaxHit(p,n,1,1)==39,"Imbued slayer15 then tome after equipment floor");
  for(int amulet:new int[]{12018,25278,26782}){p.playerEquipment[2]=amulet;ok(MagicTargetEquipment.bonus(p,n)==0.2&&f.getMaxHit(p,n,1,1)==40,"Salve ei priority20 no Slayer stacking "+amulet);}
  for(int amulet:new int[]{12017,25250,26763}){p.playerEquipment[2]=amulet;ok(MagicTargetEquipment.bonus(p,n)==0.15&&f.getMaxHit(p,n,1,1)==39,"Salve i15 "+amulet);}
  p.playerEquipment[2]=10588;ok(MagicTargetEquipment.bonus(p,n)==0.15,"Unimbued Salve e cannot disable magic task bonus");p.playerEquipment[0]=11864;ok(MagicTargetEquipment.bonus(p,n)==0&&f.getMaxHit(p,n,1,1)==34,"No unimbued helm/amulet magic boost");
  p.playerEquipment[2]=-1;for(int start:new int[]{11774,25266,26771})for(int i=0;i<11;i++){p.playerEquipment[0]=start+i;ok(MagicTargetEquipment.bonus(p,n)==0.15,"All eleven imbued mask charge models "+(start+i));}
  p.getSlayer().setTask(Optional.empty());ok(MagicTargetEquipment.bonus(p,n)==0,"Off-task no helmet bonus");
  Player target=actor();java.lang.reflect.Method roll=MagicCombatFormula.class.getDeclaredMethod("getAttackRoll",io.xeros.model.entity.Entity.class,io.xeros.model.entity.Entity.class);roll.setAccessible(true);
  p=actor();spell(p,1185);int base=(int)roll.invoke(f,p,target);p.playerEquipment[5]=25574;p.getTomeOfWater().setTotalCharges(1);ok((int)roll.invoke(f,p,target)==(int)Math.floor(base*1.2),"Water applies20percent to attack roll, not final hit probability");
  p.playerEquipment[5]=-1;for(int staff:new int[]{11998,12000}){p.playerEquipment[3]=staff;p.playerMagicBook=0;ok((int)roll.invoke(f,p,target)==(int)Math.floor(base*1.1),"Smoke staff modern accuracy "+staff);spell(p,1189);ok(f.getMaxHit(p,target,1,1)==22,"Smoke staff modern damage "+staff);p.playerMagicBook=1;spell(p,12891);ok(f.getMaxHit(p,target,1,1)==30&&((int)roll.invoke(f,p,target))==base,"Smoke staff excluded from ancient damage/accuracy");spell(p,1185);}
  System.out.println("MAGIC_EQUIPMENT_IMBUED_SLAYER15_SALVE_ALL_SIX_2022_VARIANTS_PRIORITY_NO_STACK_33_MASK_MODELS_OFF_TASK_UNIMBUED_EXCLUSIONS_TOME_FLOOR_ORDER_AND_BOTH_SMOKE_STAVES_MODERN_ONLY_ACCURACY_DAMAGE_OK");
 }
 static void multiCast(){
  Player p=CombatMagicPaymentCheck.caster(12891,25574);p.absX=3180;p.absY=3780;p.setIndex(1);PlayerHandler.players[1]=p;ok(p.getPosition().inMulti(),"Real multi area");for(int x=3178;x<3186;x++)for(int y=3778;y<3785;y++)p.getRegionProvider().get(x,y).setClipFlags(x,y,0,0,0);
  NPC[] targets={new NPC(1,new Position(3182,3780,0)),new NPC(1,new Position(3182,3781,0)),new NPC(1,new Position(3183,3780,0))};for(NPC n:targets){n.getHealth().setMaximumHealth(1000);n.getHealth().reset();n.randomWalk=false;}
  MagicCombatFormula original=MagicCombatFormula.STANDARD;Random oldRandom=HitDispatcher.rand;
  try{MagicCombatFormula.STANDARD=new MagicCombatFormula(0);HitDispatcher.rand=new Random(){public double nextDouble(){return 0;}};CombatMagicPaymentCheck.give(p,560,4);CombatMagicPaymentCheck.give(p,565,2);int xp=p.playerXP[6],hp=p.playerXP[3];ok(HitDispatcher.getHitEntity(p,targets[0]).getMultiHitEntities(false).size()==2,"Two valid secondary NPCs");p.attacking.attackEntity(targets[0]);ok(p.playerXP[6]==xp+52&&p.playerXpTenths[6]==0&&p.playerXP[3]==hp,"One base cast XP despite three real targets, zero damage control");for(NPC n:targets)ok(n.freezeTimer==32,"All three actual targets received Ice Barrage freeze");ok(CombatMagicPaymentCheck.count(p,560)==0&&CombatMagicPaymentCheck.count(p,565)==0&&p.getTomeOfWater().getTotalCharges()==1,"One rune cost; Ice never spends tome pages");}
  finally{MagicCombatFormula.STANDARD=original;HitDispatcher.rand=oldRandom;for(NPC n:targets)n.unregisterInstant();PlayerHandler.players[1]=null;}
  System.out.println("MAGIC_ACTUAL_MULTI_AREA_THREE_REGISTERED_NPCS_ICE_BARRAGE_32_TICK_FREEZE_EACH_SINGLE52_BASE_XP_SINGLE_FOUR_DEATH_TWO_BLOOD_COST_NO_TOME_CHARGE_ZERO_DAMAGE_CONTROL_OK");
 }
 public static void main(String[]args){try{Thread.currentThread().setName("GameThread");System.setProperty("solo.mode","true");System.setProperty("solo.xp","1");Server.startServerless();Configuration.BONUS_SKILL=-1;java.lang.reflect.Field boosts=io.xeros.content.boosts.Boosts.class.getDeclaredField("boosts");boosts.setAccessible(true);boosts.set(null,Collections.emptyList());xp();freezes();curses();damage();targetEquipment();multiCast();System.out.println("COMBAT_MAGIC_EFFECTS_ALL_CHECKS_PASSED");System.exit(0);}catch(Throwable t){t.printStackTrace();System.exit(1);}}
